    # Define a function to compute the shortest path
    def dijkstra(graph, source, target):
        # Initialize distances and paths
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        visited = {}
        path = {}

        while distances:
            # Get the node with the smallest known distance
            current_node = min(distances, key=distances.get)
            if current_node == target:
                break
            visited[current_node] = distances[current_node]
            del distances[current_node]

            # Explore neighbors
            for neighbor, weight in graph.get(current_node, []):
                distance = distances[current_node] + weight
                if distance < distances.get(neighbor, float('inf')):
                    distances[neighbor] = distance
                    path[neighbor] = [current_node, neighbor]

        return distances[target], path.get(target, None)

    # Start the Dijkstra's algorithm
    return dijkstra(graph, source, target)

