def shortest_path(graph, source, target):
    # Initialize variables
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    previous_nodes = {node: None for node in graph}
    unvisited = list(graph.keys())

    # Dijkstra's algorithm
    while unvisited:
        # Find the unvisited node with the smallest distance
        current_min_node = min(unvisited, key=lambda node: distances[node])

        # If the smallest distance is infinity, we can't reach the target
        if distances[current_min_node] == float('inf'):
            return (float('inf'), None)

        unvisited.remove(current_min_node)

        # Explore neighbors
        for neighbor, weight in graph[current_min_node]:
            distance_through_current = distances[current_min_node] + weight
            if distance_through_current < distances[neighbor]:
                distances[neighbor] = distance_through_current
                previous_nodes[neighbor] = current_min_node

    # Reconstruct the path from source to target
    path = []
    node = target
    while node:
        path.insert(0, node)
        node = previous_nodes[node]
    return (distances[target], path)

