def shortest_path(graph, source, target):
    import heapq

    def dijkstra(graph, source):
        # Priority queue with (distance, node) tuples
        queue = [(0, source)]
        # Dictionary to track the shortest distance to each node
        distances = {vertex: float('inf') for vertex in graph}
        distances[source] = 0
        # Dictionary to track the shortest path to each node
        previous_nodes = {vertex: None for vertex in graph}

        while queue:
            current_distance, current_vertex = heapq.heappop(queue)

            if current_distance > distances[current_vertex]:
                continue

            for neighbor, weight in graph.get(current_vertex, []):
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    previous_nodes[neighbor] = current_vertex
                    heapq.heappush(queue, (distance, neighbor))

        return distances, previous_nodes

    distances, previous_nodes = dijkstra(graph, source)
    if distances[target] == float('inf'):
        return float('inf'), None

    # Reconstruct the path from target to source
    path = []
    current_vertex = target
    while current_vertex:
        path.append(current_vertex)
        current_vertex = previous_nodes.get(current_vertex)
    path.reverse()

    return (distances[target], path)
