def shortest_path(graph, source, target):
    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    previous_nodes = {node: None for node in graph}
    distances[source] = 0
    path = None

    # While target is not reached
    while target in distances:
        # Consider each neighbor of the current node
        for neighbor, weight in graph[target]:
            # Calculate the distance through the current node
            distance_through_current = distances[target] + weight
            # If this is a shorter path found, remember it and its origin
            if distance_through_current < distances[neighbor]:
                distances[neighbor] = distance_through_current
                previous_nodes[neighbor] = target

        # Move to the unvisited node that is closest to the current node
        candidates = {node: distances[node] for node in distances if node is not target and node not in path}
        if not candidates:
            break
        target = min(candidates, key=candidates.get)

    # If the target is still not reachable, return infinity and None
    if target is None:
        return float('inf'), None

    # Reconstruct the path
    path = []
    current_node = target
    while current_node is not None:
        path.insert(0, current_node)
        current_node = previous_nodes.get(current_node)
    return distances[target], path
