def shortest_path(graph, source, target):
    # Initialize the came_from and g_score arrays
    came_from = {}
    g_score = {node: float("infinity") for node in graph}
    g_score[source] = 0

    # Initialize the open set with the source node
    open_set = [source]

    # While the open set is not empty
    while open_set:
        # Get the node in open_set with the smallest g_score
        current = min(open_set, key=lambda node: g_score[node])

        # If we have reached the target node, return the path
        if current == target:
            path = []
            while current in came_from:
                path.insert(0, current)
                current = came_from[current]
            path.insert(0, source)
            return (g_score[target], path)

        # Remove the current node from the open set
        open_set.remove(current)

        # Explore the neighbors
        for neighbor, weight in graph.get(current, []):
            # Consider the path from the current node to the neighbor through the current node
            tentative_g_score = g_score[current] + weight

            # If this path is better than any previously known path to the neighbor
            if tentative_g_score < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g_score
                # Add the neighbor to the open set if it is not already in
                if neighbor not in open_set:
                    open_set.append(neighbor)

    # If the target node is not reachable, return infinity and None
    return (float("inf"), None)
