    distances[source] = 0  # Distance from source to itself is 0
    predecessors = {node: None for node in graph}  # To keep track of the path

    # Dictionary to keep track of whether a node has been processed
    processed = {node: False for node in graph}

    # Priority queue to keep track of the nodes to be processed
    from heapq import heappush, heappop
    queue = [(0, source)]  # The priority is the distance from source

    while queue:
        current_distance, current_node = heappop(queue)

        if processed[current_node]:
            continue  # This node has already been processed

        processed[current_node] = True

        # Update the distance to each neighbor
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                predecessors[neighbor] = current_node
                if neighbor == target:
                    # We found the target, reconstruct the path
                    path = [neighbor]
                    while path[-1] != source:
                        path.append(predecessors[path[-1]])
                    path.reverse()
                    return (distance, path)

                heappush(queue, (distance, neighbor))

    # If we exit the loop without finding the target, the target is unreachable
    return (float("inf"), None)
